body.script:
(() => {
  const html = document.documentElement;
  const root = document.getElementById("root");
  const cover = document.getElementById("peel-entry");
  const recovery = document.getElementById("peel-recovery");
  const loadingNote = document.getElementById("peel-loading-note");
  const styles = Array.from(document.querySelectorAll("link[data-peel-style]"));
  const previousInert = root.inert;
  const retryURL = new URL(location.href);
  document.getElementById("peel-retry").href = retryURL.href;
  retryURL.searchParams.set("graphics", "off");
  document.getElementById("peel-light").href = retryURL.href;
  let appReady = false;
  let requestedReason = null;
  let deadline;
  let resolveStyles;
  const stylesLoaded = new Promise((resolve) => { resolveStyles = resolve; });
  const entry = window.__peelEntry = {
    done: false,
    stylesLoaded,
    appReady() {
      appReady = true;
      if (requestedReason) entry.finish(requestedReason);
    },
    stylesReady() {
      if (styles.every((link) => link.dataset.loaded === "true")) resolveStyles();
      if (requestedReason) entry.finish(requestedReason);
    },
    recover(reason) {
      if (entry.done) return;
      html.dataset.peelEntry = "recovery";
      cover.dataset.reason = reason;
      recovery.style.display = "block";
      loadingNote.hidden = true;
    },
    finish(reason) {
      if (entry.done) return;
      requestedReason = reason;
      // A deadline may reveal the usable HTML/photo fallback, but never
      // an empty app root or a page whose styles still haven't arrived.
      if (!appReady || !styles.every((link) => link.dataset.loaded === "true")) {
        if (reason === "timeout") entry.recover(reason);
        return;
      }
      entry.done = true;
      clearTimeout(deadline);
      html.dataset.peelEntry = reason;
      root.inert = previousInert;
      if (reason === "ready" && cover.animate && !matchMedia("(prefers-reduced-motion: reduce)").matches) {
        cover.style.display = "grid";
        cover.style.pointerEvents = "none";
        const reveal = cover.animate([{ transform: "translateY(0)" }, { transform: "translateY(-101%)" }], {duration: 550, easing: "cubic-bezier(.76,0,.24,1)", fill: "forwards"});
        reveal.finished.then(() => cover.remove(), () => cover.remove());
        setTimeout(() => cover.remove(), 700);
      } else cover.remove();
      window.removeEventListener("error", bootError, true);
    }
  };
  const bootError = (event) => {
    if (!appReady && (event.target?.tagName === "SCRIPT" || event.error)) entry.recover("app-error");
  };
  deadline = setTimeout(() => entry.finish("timeout"), 12000);
  window.addEventListener("error", bootError, true);
  root.inert = true;
  entry.stylesReady();
  if (styles.some((link) => link.dataset.failed === "true")) entry.recover("styles-error");
})();
